<?php

namespace Asn1Tools\Tests\E2E;

use Asn1Tools\AsnEncodingRules;
use Asn1Tools\AsnReader;
use Asn1Tools\AsnWriter;
use Asn1Tools\BitString;
use Asn1Tools\Tag\AsnTag;
use Asn1Tools\Tag\TagClass;
use Asn1Tools\Tag\UniversalTag;
use BcMath\Number;
use Closure;
use DateTimeImmutable;
use Generator;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;

/**
 * Tests that the bytes generated by AsnWriter can be decoded by AsnReader.
 */
class AsnWriterToAsnReaderTest extends TestCase
{
    /**
     * DER is a subset of BER, so the output of AsnWriter must be readable with both rules.
     *
     * @return Generator<string, array{AsnEncodingRules}>
     */
    public static function encodingRulesProvider(): Generator
    {
        yield 'DER' => [AsnEncodingRules::DER];
        yield 'BER' => [AsnEncodingRules::BER];
    }

    /**
     * @return Generator<string, array{Closure(AsnWriter): AsnWriter, Closure(AsnReader): mixed, mixed}>
     */
    public static function valueProvider(): Generator
    {
        yield 'integer zero' => [fn (AsnWriter $w) => $w->writeInteger(0), fn (AsnReader $r) => $r->readInteger(), new Number(0)];
        yield 'integer 127' => [fn (AsnWriter $w) => $w->writeInteger(127), fn (AsnReader $r) => $r->readInteger(), new Number(127)];
        yield 'integer 128' => [fn (AsnWriter $w) => $w->writeInteger(128), fn (AsnReader $r) => $r->readInteger(), new Number(128)];
        yield 'integer PHP_INT_MAX' => [
            fn (AsnWriter $w) => $w->writeInteger(PHP_INT_MAX),
            fn (AsnReader $r) => $r->readInteger(),
            new Number(PHP_INT_MAX),
        ];
        yield 'big integer' => [
            fn (AsnWriter $w) => $w->writeInteger(new Number('116642482170122253773863463039760007017')),
            fn (AsnReader $r) => $r->readInteger(),
            new Number('116642482170122253773863463039760007017'),
        ];
        yield 'object identifier' => [
            fn (AsnWriter $w) => $w->writeObjectIdentifier('1.2.840.113549.1.7.2'),
            fn (AsnReader $r) => $r->readObjectIdentifier(),
            '1.2.840.113549.1.7.2',
        ];
        yield 'object identifier with large arc' => [
            fn (AsnWriter $w) => $w->writeObjectIdentifier('1.3.6.1.4.1.311.21.20.4294967295'),
            fn (AsnReader $r) => $r->readObjectIdentifier(),
            '1.3.6.1.4.1.311.21.20.4294967295',
        ];
        yield 'null' => [fn (AsnWriter $w) => $w->writeNull(), fn (AsnReader $r) => $r->readNull(), null];
        yield 'boolean true' => [fn (AsnWriter $w) => $w->writeBoolean(true), fn (AsnReader $r) => $r->readBoolean(), true];
        yield 'boolean false' => [fn (AsnWriter $w) => $w->writeBoolean(false), fn (AsnReader $r) => $r->readBoolean(), false];
        yield 'empty octet string' => [fn (AsnWriter $w) => $w->writeOctetString(''), fn (AsnReader $r) => $r->readOctetString(), ''];
        yield 'binary octet string' => [
            fn (AsnWriter $w) => $w->writeOctetString("\x00\x80\xFF"),
            fn (AsnReader $r) => $r->readOctetString(),
            "\x00\x80\xFF",
        ];
        yield 'octet string with 2 bytes length' => [
            fn (AsnWriter $w) => $w->writeOctetString(str_repeat("\xAB", 300)),
            fn (AsnReader $r) => $r->readOctetString(),
            str_repeat("\xAB", 300),
        ];
        yield 'octet string with 3 bytes length' => [
            fn (AsnWriter $w) => $w->writeOctetString(str_repeat("\xAB", 70000)),
            fn (AsnReader $r) => $r->readOctetString(),
            str_repeat("\xAB", 70000),
        ];
        yield 'bit string' => [
            fn (AsnWriter $w) => $w->writeBitString(new BitString("\xFF\x80", 7)),
            fn (AsnReader $r) => $r->readBitString(),
            new BitString("\xFF\x80", 7),
        ];
        yield 'empty bit string' => [
            fn (AsnWriter $w) => $w->writeBitString(new BitString('', 0)),
            fn (AsnReader $r) => $r->readBitString(),
            new BitString('', 0),
        ];
        yield 'UTF8 string' => [
            fn (AsnWriter $w) => $w->writeCharacterString(UniversalTag::UTF8_STRING, '東京都千代田区'),
            fn (AsnReader $r) => $r->readCharacterString(UniversalTag::UTF8_STRING),
            '東京都千代田区',
        ];
        yield 'printable string' => [
            fn (AsnWriter $w) => $w->writeCharacterString(UniversalTag::PRINTABLE_STRING, 'JP'),
            fn (AsnReader $r) => $r->readCharacterString(UniversalTag::PRINTABLE_STRING),
            'JP',
        ];
        yield 'IA5 string' => [
            fn (AsnWriter $w) => $w->writeCharacterString(UniversalTag::IA5_STRING, 'https://example.com/'),
            fn (AsnReader $r) => $r->readCharacterString(UniversalTag::IA5_STRING),
            'https://example.com/',
        ];
        yield 'UTC time' => [
            fn (AsnWriter $w) => $w->writeUtcTime(new DateTimeImmutable('2026-05-10 12:52:12+0000')),
            fn (AsnReader $r) => $r->readUtcTime(),
            new DateTimeImmutable('2026-05-10 12:52:12+0000'),
        ];
        yield 'UTC time from non-UTC time zone' => [
            fn (AsnWriter $w) => $w->writeUtcTime(new DateTimeImmutable('2026-05-10 21:52:12+0900')),
            fn (AsnReader $r) => $r->readUtcTime(),
            new DateTimeImmutable('2026-05-10 12:52:12+0000'),
        ];
        yield 'generalized time' => [
            fn (AsnWriter $w) => $w->writeGeneralizedTime(new DateTimeImmutable('2076-01-19 06:02:47+0000')),
            fn (AsnReader $r) => $r->readGeneralizedTime(),
            new DateTimeImmutable('2076-01-19 06:02:47+0000'),
        ];
    }

    /**
     * @param Closure(AsnWriter): AsnWriter $write
     * @param Closure(AsnReader): mixed $read
     */
    #[DataProvider('valueProvider')]
    public function testValue(Closure $write, Closure $read, mixed $expected): void
    {
        // Wrap the value in a sequence to check that the encoded length matches the actual contents.
        $encoded = new AsnWriter()->writeSequence(function (AsnWriter $writer) use ($write) {
            $write($writer);
        })->encode();

        foreach ([AsnEncodingRules::DER, AsnEncodingRules::BER] as $encodingRule) {
            $sequence = new AsnReader($encoded, $encodingRule)->readSequence();
            $this->assertEquals($expected, $read($sequence));
            $this->assertTrue($sequence->isEOC);
        }
    }

    #[DataProvider('encodingRulesProvider')]
    public function testMixedStructure(AsnEncodingRules $encodingRule): void
    {
        $encoded = new AsnWriter()->writeSequence(function (AsnWriter $writer) {
            $writer
                ->writeObjectIdentifier('1.2.840.113549.1.7.2')
                ->writeSequenceWithTagNumber(AsnTag::fromEachBits(TagClass::ContextSpecific, 0, true), function (AsnWriter $writer) {
                    $writer->writeInteger(new Number('116642482170122253773863463039760007017'));
                })
                ->writeSetOf(function (AsnWriter $writer) {
                    $writer->writeSequence(function (AsnWriter $writer) {
                        $writer->writeBoolean(true)->writeOctetString('octets');
                    });
                })
                ->writeBitString(new BitString("\xAB\xCD", 0))
                ->writeUtcTime(new DateTimeImmutable('2026-05-10 12:52:12+0000'))
                ->writeGeneralizedTime(new DateTimeImmutable('2076-01-19 06:02:47+0000'))
                ->writeCharacterString(UniversalTag::IA5_STRING, 'https://example.com/')
                ->writeNull();
        })->encode();

        $sequence = new AsnReader($encoded, $encodingRule)->readSequence();
        $this->assertSame('1.2.840.113549.1.7.2', $sequence->readObjectIdentifier());
        $this->assertEquals(
            new Number('116642482170122253773863463039760007017'),
            $sequence->readSequenceWithTagNumber(AsnTag::fromEachBits(TagClass::ContextSpecific, 0, true))->readInteger(),
        );
        $inner = $sequence->readSetOf()->readSequence();
        $this->assertTrue($inner->readBoolean());
        $this->assertSame('octets', $inner->readOctetString());
        $this->assertEquals(new BitString("\xAB\xCD", 0), $sequence->readBitString());
        $this->assertEquals(new DateTimeImmutable('2026-05-10 12:52:12+0000'), $sequence->readUtcTime());
        $this->assertEquals(new DateTimeImmutable('2076-01-19 06:02:47+0000'), $sequence->readGeneralizedTime());
        $this->assertSame('https://example.com/', $sequence->readCharacterString(UniversalTag::IA5_STRING));
        $sequence->readNull();
        $this->assertTrue($sequence->isEOC);
    }

    #[DataProvider('encodingRulesProvider')]
    public function testSetOfIsReadInSortedOrder(AsnEncodingRules $encodingRule): void
    {
        $encoded = new AsnWriter()->writeSetOf(function (AsnWriter $writer) {
            $writer->writeInteger(256)->writeInteger(3)->writeInteger(1);
        })->encode();

        $set = new AsnReader($encoded, $encodingRule)->readSetOf();
        $values = [];
        while (!$set->isEOC) {
            $values[] = $set->readInteger();
        }

        $this->assertEquals([new Number(1), new Number(3), new Number(256)], $values);
    }

    #[DataProvider('encodingRulesProvider')]
    public function testDeeplyNestedSequenceWithLongFormLength(AsnEncodingRules $encodingRule): void
    {
        $writeNested = function (AsnWriter $writer, int $depth) use (&$writeNested): void {
            if ($depth === 0) {
                $writer->writeOctetString(str_repeat("\xAB", 70000));
                return;
            }
            $writer->writeSequence(fn (AsnWriter $writer) => $writeNested($writer, $depth - 1));
        };
        $writer = new AsnWriter();
        $writeNested($writer, 10);

        $reader = new AsnReader($writer->encode(), $encodingRule);
        for ($i = 0; $i < 10; $i++) {
            $reader = $reader->readSequence();
        }

        $this->assertSame(str_repeat("\xAB", 70000), $reader->readOctetString());
        $this->assertTrue($reader->isEOC);
    }

    #[DataProvider('encodingRulesProvider')]
    public function testCertificate(AsnEncodingRules $encodingRule): void
    {
        $issuer = [
            '2.5.4.6' => 'JP',
            '2.5.4.8' => 'Tokyo',
            '2.5.4.7' => 'Chiyoda',
            '2.5.4.10' => 'Local Development',
            '2.5.4.3' => 'Local Development Intermediate CA',
        ];
        $subject = [...$issuer, '2.5.4.3' => 'localhost'];
        $publicKey = random_bytes(270);
        $signature = random_bytes(256);
        // Extension values are DER encoded values wrapped in an OCTET STRING.
        $basicConstraints = new AsnWriter()->writeSequence(function (AsnWriter $writer) {
            $writer->writeBoolean(false);
        })->encode();

        $encoded = new AsnWriter()->writeSequence(function (AsnWriter $certificate) use ($issuer, $subject, $publicKey, $signature, $basicConstraints) {
            $certificate->writeSequence(function (AsnWriter $tbsCertificate) use ($issuer, $subject, $publicKey, $basicConstraints) {
                $tbsCertificate
                    ->writeSequenceWithTagNumber(AsnTag::fromEachBits(TagClass::ContextSpecific, 0, true), function (AsnWriter $writer) {
                        $writer->writeInteger(2);
                    })
                    ->writeInteger(3)
                    ->writeSequence($this->writeAlgorithmIdentifier('1.2.840.113549.1.1.11'))
                    ->writeSequence($this->writeName($issuer))
                    ->writeSequence(function (AsnWriter $validity) {
                        $validity
                            ->writeUtcTime(new DateTimeImmutable('2026-05-10 12:52:12+0000'))
                            ->writeGeneralizedTime(new DateTimeImmutable('2050-05-10 12:52:12+0000'));
                    })
                    ->writeSequence($this->writeName($subject))
                    ->writeSequence(function (AsnWriter $subjectPublicKeyInfo) use ($publicKey) {
                        $subjectPublicKeyInfo
                            ->writeSequence($this->writeAlgorithmIdentifier('1.2.840.113549.1.1.1'))
                            ->writeBitString(new BitString($publicKey, 0));
                    })
                    ->writeSequenceWithTagNumber(AsnTag::fromEachBits(TagClass::ContextSpecific, 3, true), function (AsnWriter $writer) use ($basicConstraints) {
                        $writer->writeSequence(function (AsnWriter $extensions) use ($basicConstraints) {
                            $extensions->writeSequence(function (AsnWriter $extension) use ($basicConstraints) {
                                $extension
                                    ->writeObjectIdentifier('2.5.29.19')
                                    ->writeBoolean(true)
                                    ->writeOctetString($basicConstraints);
                            });
                        });
                    });
            })
                ->writeSequence($this->writeAlgorithmIdentifier('1.2.840.113549.1.1.11'))
                ->writeBitString(new BitString($signature, 0));
        })->encode();

        $certificate = new AsnReader($encoded, $encodingRule)->readSequence();
        $tbsCertificate = $certificate->readSequence();

        $version = $tbsCertificate->readSequenceWithTagNumber(AsnTag::fromEachBits(TagClass::ContextSpecific, 0, true))->readInteger();
        $this->assertEquals(new Number(2), $version);
        $this->assertEquals(new Number(3), $tbsCertificate->readInteger());
        $this->assertAlgorithmIdentifier('1.2.840.113549.1.1.11', $tbsCertificate->readSequence());
        $this->assertSame($issuer, $this->extractName($tbsCertificate->readSequence()));

        $validity = $tbsCertificate->readSequence();
        $this->assertEquals(new DateTimeImmutable('2026-05-10 12:52:12+0000'), $validity->readUtcTime());
        $this->assertEquals(new DateTimeImmutable('2050-05-10 12:52:12+0000'), $validity->readGeneralizedTime());

        $this->assertSame($subject, $this->extractName($tbsCertificate->readSequence()));

        $subjectPublicKeyInfo = $tbsCertificate->readSequence();
        $this->assertAlgorithmIdentifier('1.2.840.113549.1.1.1', $subjectPublicKeyInfo->readSequence());
        $this->assertEquals(new BitString($publicKey, 0), $subjectPublicKeyInfo->readBitString());

        $extension = $tbsCertificate
            ->readSequenceWithTagNumber(AsnTag::fromEachBits(TagClass::ContextSpecific, 3, true))
            ->readSequence()
            ->readSequence();
        $this->assertSame('2.5.29.19', $extension->readObjectIdentifier());
        $this->assertTrue($extension->readBoolean());
        $this->assertFalse(new AsnReader($extension->readOctetString(), $encodingRule)->readSequence()->readBoolean());
        $this->assertTrue($tbsCertificate->isEOC);

        $this->assertAlgorithmIdentifier('1.2.840.113549.1.1.11', $certificate->readSequence());
        $this->assertEquals(new BitString($signature, 0), $certificate->readBitString());
        $this->assertTrue($certificate->isEOC);
    }

    /**
     * @return Closure(AsnWriter): void
     */
    private function writeAlgorithmIdentifier(string $oid): Closure
    {
        return function (AsnWriter $writer) use ($oid) {
            $writer->writeObjectIdentifier($oid)->writeNull();
        };
    }

    /**
     * @param array<string, string> $attributes
     * @return Closure(AsnWriter): void
     */
    private function writeName(array $attributes): Closure
    {
        return function (AsnWriter $writer) use ($attributes) {
            foreach ($attributes as $oid => $value) {
                $writer->writeSetOf(function (AsnWriter $writer) use ($oid, $value) {
                    $writer->writeSequence(function (AsnWriter $writer) use ($oid, $value) {
                        $writer->writeObjectIdentifier((string) $oid)->writeCharacterString(UniversalTag::UTF8_STRING, $value);
                    });
                });
            }
        };
    }

    private function assertAlgorithmIdentifier(string $expectedOid, AsnReader $algorithmIdentifier): void
    {
        $this->assertSame($expectedOid, $algorithmIdentifier->readObjectIdentifier());
        $algorithmIdentifier->readNull();
        $this->assertTrue($algorithmIdentifier->isEOC);
    }

    /**
     * @return array<string, string>
     */
    private function extractName(AsnReader $asnReader): array
    {
        $name = [];
        while (!$asnReader->isEOC) {
            $attribute = $asnReader->readSetOf()->readSequence();
            $oid = $attribute->readObjectIdentifier();
            $value = $attribute->readCharacterString(UniversalTag::UTF8_STRING);
            $name[$oid] = $value;
        }
        return $name;
    }
}
